// Helper functions for matrix operations can be added here if needed

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *cov_array;

    // Parse NumPy arrays
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &cov_array))
        return NULL;

    // Coerce to contiguous float64 arrays (no copy if already so)
    PyArrayObject *w = (PyArrayObject *)PyArray_FROM_OTF(weights_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *S = NULL;
    if (w) {
        S = (PyArrayObject *)PyArray_FROM_OTF(cov_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    }
    if (!w || !S) {
        Py_XDECREF(w);
        Py_XDECREF(S);
        return NULL;
    }

    Py_ssize_t n = PyArray_DIM(w, 0);
    if (PyArray_NDIM(S) != 2 || PyArray_DIM(S, 0) != n || PyArray_DIM(S, 1) != n) {
        PyErr_Format(PyExc_ValueError,
                     "weights length %lld must equal cov_matrix shape (%lld, %lld)",
                     (long long)n, (long long)PyArray_DIM(S, 0), (long long)PyArray_DIM(S, 1));
        Py_DECREF(w);
        Py_DECREF(S);
        return NULL;
    }

    const double *w_data = (const double *)PyArray_DATA(w);
    const double *S_data = (const double *)PyArray_DATA(S);

    // Step 1: temp = S * x (matrix-vector product)
    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (!temp) {
        PyErr_NoMemory();
        Py_DECREF(w);
        Py_DECREF(S);
        return NULL;
    }
    for (Py_ssize_t i = 0; i < n; i++) {
        double row_sum = 0.0;
        const double *row = S_data + (size_t)i * n;
        for (Py_ssize_t j = 0; j < n; j++) {
            row_sum += row[j] * w_data[j];
        }
        temp[i] = row_sum;
    }

    // Step 2: risk_squared = x^T * temp (dot product)
    double risk_squared = 0.0;
    for (Py_ssize_t i = 0; i < n; i++) {
        risk_squared += w_data[i] * temp[i];
    }
    free(temp);
    Py_DECREF(w);
    Py_DECREF(S);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *returns_array;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &returns_array))
        return NULL;

    PyArrayObject *w = (PyArrayObject *)PyArray_FROM_OTF(weights_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *r = NULL;
    if (w) {
        r = (PyArrayObject *)PyArray_FROM_OTF(returns_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    }
    if (!w || !r) {
        Py_XDECREF(w);
        Py_XDECREF(r);
        return NULL;
    }

    Py_ssize_t n = PyArray_DIM(w, 0);
    if (PyArray_DIM(r, 0) != n) {
        PyErr_Format(PyExc_ValueError,
                     "weights length %lld must equal returns length %lld",
                     (long long)n, (long long)PyArray_DIM(r, 0));
        Py_DECREF(w);
        Py_DECREF(r);
        return NULL;
    }

    const double *w_data = (const double *)PyArray_DATA(w);
    const double *r_data = (const double *)PyArray_DATA(r);

    // return = weights^T * returns (dot product)
    double total_return = 0.0;
    for (Py_ssize_t i = 0; i < n; i++) {
        total_return += w_data[i] * r_data[i];
    }
    Py_DECREF(w);
    Py_DECREF(r);

    return PyFloat_FromDouble(total_return);
}

