/*
 * High-performance portfolio calculations using C extension
 *
 * Implements the optimized C functions below.
 * Uses the NumPy C API for zero-copy array access when inputs are
 * already NumPy arrays; otherwise converts Python sequences to
 * contiguous double buffers directly in C (faster than np.array on
 * nested lists).
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

// Helper functions for matrix operations can be added here if needed

/*
 * Convert a Python sequence (or ndarray) of numbers to a malloc'd
 * 1D contiguous double buffer. On success returns the buffer and
 * sets *n_out to its length; on failure returns NULL with an
 * exception set. The caller must free() the returned buffer.
 */
static double* seq_to_doubles(PyObject *obj, Py_ssize_t *n_out)
{
    *n_out = 0;
    Py_ssize_t n, i;
    double *out = NULL;

    if (PyArray_Check(obj)) {
        PyArrayObject *a = (PyArrayObject *)PyArray_FROM_OTF(
            obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
        if (!a)
            return NULL;
        n = PyArray_DIM(a, 0);
        out = (double *)malloc((size_t)n * sizeof(double));
        if (!out) {
            Py_DECREF(a);
            PyErr_NoMemory();
            return NULL;
        }
        memcpy(out, PyArray_DATA(a), (size_t)n * sizeof(double));
        Py_DECREF(a);
    } else {
        PyObject *seq = PySequence_Fast(obj, "expected a sequence of numbers");
        if (!seq)
            return NULL;
        n = PySequence_Fast_GET_SIZE(seq);
        out = (double *)malloc((size_t)n * sizeof(double));
        if (!out) {
            Py_DECREF(seq);
            PyErr_NoMemory();
            return NULL;
        }
        for (i = 0; i < n; i++) {
            out[i] = PyFloat_AsDouble(PySequence_Fast_GET_ITEM(seq, i));
            if (out[i] == -1.0 && PyErr_Occurred()) {
                free(out);
                Py_DECREF(seq);
                return NULL;
            }
        }
        Py_DECREF(seq);
    }

    *n_out = n;
    return out;
}

/*
 * Convert a Python 2D sequence (or 2D ndarray) to a malloc'd
 * row-major double buffer. On success returns the buffer and sets
 * *rows_out / *cols_out; on failure returns NULL with an exception
 * set. The caller must free() the returned buffer.
 */
static double* seq2_to_doubles(PyObject *obj, Py_ssize_t *rows_out,
                               Py_ssize_t *cols_out)
{
    *rows_out = 0;
    *cols_out = 0;
    Py_ssize_t rows, cols, i, j;
    double *out = NULL;

    if (PyArray_Check(obj)) {
        PyArrayObject *a = (PyArrayObject *)PyArray_FROM_OTF(
            obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
        if (!a)
            return NULL;
        if (PyArray_NDIM(a) != 2) {
            PyErr_SetString(PyExc_ValueError, "expected a 2D array for cov_matrix");
            Py_DECREF(a);
            return NULL;
        }
        rows = PyArray_DIM(a, 0);
        cols = PyArray_DIM(a, 1);
        out = (double *)malloc((size_t)rows * (size_t)cols * sizeof(double));
        if (!out) {
            Py_DECREF(a);
            PyErr_NoMemory();
            return NULL;
        }
        memcpy(out, PyArray_DATA(a), (size_t)rows * (size_t)cols * sizeof(double));
        Py_DECREF(a);
    } else {
        PyObject *outer = PySequence_Fast(obj, "expected a 2D sequence for cov_matrix");
        if (!outer)
            return NULL;
        rows = PySequence_Fast_GET_SIZE(outer);
        cols = 0;
        if (rows > 0) {
            PyObject *row0 = PySequence_Fast(PySequence_Fast_GET_ITEM(outer, 0),
                                             "cov_matrix rows must be sequences of numbers");
            if (!row0) {
                Py_DECREF(outer);
                return NULL;
            }
            cols = PySequence_Fast_GET_SIZE(row0);
            out = (double *)malloc((size_t)rows * (size_t)cols * sizeof(double));
            if (!out) {
                Py_DECREF(row0);
                Py_DECREF(outer);
                PyErr_NoMemory();
                return NULL;
            }
            for (i = 0; i < rows; i++) {
                PyObject *row = (i == 0) ? row0
                    : PySequence_Fast(PySequence_Fast_GET_ITEM(outer, i),
                                      "cov_matrix rows must be sequences of numbers");
                if (!row) {
                    Py_DECREF(row0);
                    Py_DECREF(outer);
                    free(out);
                    return NULL;
                }
                if (PySequence_Fast_GET_SIZE(row) != cols) {
                    PyErr_SetString(PyExc_ValueError,
                                    "cov_matrix rows have inconsistent lengths");
                    if (i != 0)
                        Py_DECREF(row);
                    Py_DECREF(row0);
                    Py_DECREF(outer);
                    free(out);
                    return NULL;
                }
                double *dst = out + (size_t)i * (size_t)cols;
                for (j = 0; j < cols; j++) {
                    dst[j] = PyFloat_AsDouble(PySequence_Fast_GET_ITEM(row, j));
                    if (dst[j] == -1.0 && PyErr_Occurred()) {
                        if (i != 0)
                            Py_DECREF(row);
                        Py_DECREF(row0);
                        Py_DECREF(outer);
                        free(out);
                        return NULL;
                    }
                }
                if (i != 0)
                    Py_DECREF(row);
            }
            Py_DECREF(row0);
        }
        Py_DECREF(outer);
    }

    *rows_out = rows;
    *cols_out = cols;
    return out;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    // Parse inputs (NumPy arrays or Python sequences)
    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    Py_ssize_t n = 0, rows = 0, cols = 0;
    double *w = seq_to_doubles(weights_obj, &n);
    double *S = NULL;
    if (w) {
        S = seq2_to_doubles(cov_obj, &rows, &cols);
    }
    if (!w || !S) {
        free(w);
        free(S);
        return NULL;
    }
    if (rows != n || cols != n) {
        PyErr_Format(PyExc_ValueError,
                     "weights length %lld must equal cov_matrix shape (%lld, %lld)",
                     (long long)n, (long long)rows, (long long)cols);
        free(w);
        free(S);
        return NULL;
    }

    // Step 1: temp = S * x (matrix-vector product)
    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (!temp) {
        free(w);
        free(S);
        PyErr_NoMemory();
        return NULL;
    }
    for (Py_ssize_t i = 0; i < n; i++) {
        double row_sum = 0.0;
        const double *row = S + (size_t)i * (size_t)n;
        for (Py_ssize_t j = 0; j < n; j++) {
            row_sum += row[j] * w[j];
        }
        temp[i] = row_sum;
    }

    // Step 2: risk_squared = x^T * temp (dot product)
    double risk_squared = 0.0;
    for (Py_ssize_t i = 0; i < n; i++) {
        risk_squared += w[i] * temp[i];
    }
    free(temp);
    free(w);
    free(S);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    Py_ssize_t n = 0, m = 0;
    double *w = seq_to_doubles(weights_obj, &n);
    double *r = NULL;
    if (w) {
        r = seq_to_doubles(returns_obj, &m);
    }
    if (!w || !r) {
        free(w);
        free(r);
        return NULL;
    }
    if (m != n) {
        PyErr_Format(PyExc_ValueError,
                     "weights length %lld must equal returns length %lld",
                     (long long)n, (long long)m);
        free(w);
        free(r);
        return NULL;
    }

    // return = weights^T * returns (dot product)
    double total_return = 0.0;
    for (Py_ssize_t i = 0; i < n; i++) {
        total_return += w[i] * r[i];
    }
    free(w);
    free(r);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}

